/**
 * @method
 * @name mercado#fetchOHLCV
 * @description fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market
 * @param {string} symbol unified symbol of the market to fetch ccxt.OHLCV data for
 * @param {string} timeframe the length of time each candle represents
 * @param {int} [since] timestamp in ms of the earliest candle to fetch
 * @param {int} [limit] the maximum amount of candles to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
 */
func  (this *mercado) FetchOHLCV(symbol interface{}, optionalArgs ...interface{}) <- chan interface{} {
            ch := make(chan interface{})
            go func() interface{} {
                defer close(ch)
                defer ccxt.ReturnPanicError(ch)
                    timeframe := ccxt.GetArg(optionalArgs, 0, "15m")
            _ = timeframe
            since := ccxt.GetArg(optionalArgs, 1, nil)
            _ = since
            limit := ccxt.GetArg(optionalArgs, 2, nil)
            _ = limit
            params := ccxt.GetArg(optionalArgs, 3, map[string]interface{} {})
            _ = params
        
            retRes8408 := (<-this.LoadMarkets())
            ccxt.PanicOnError(retRes8408)
            var market interface{} = this.Market(symbol)
            var request interface{} = map[string]interface{} {
                "resolution": this.SafeString(this.Timeframes, timeframe, timeframe),
                "symbol": ccxt.Add(ccxt.Add(ccxt.GetValue(market, "base"), "-"), ccxt.GetValue(market, "quote")),
            }
            if ccxt.IsTrue(ccxt.IsEqual(limit, nil)) {
                limit = 100 // set some default limit, as it's required if user doesn't provide it
            }
            if ccxt.IsTrue(!ccxt.IsEqual(since, nil)) {
                ccxt.AddElementToObject(request, "from", this.ParseToInt(ccxt.Divide(since, 1000)))
                ccxt.AddElementToObject(request, "to", this.Sum(ccxt.GetValue(request, "from"), ccxt.Multiply(limit, this.ParseTimeframe(timeframe))))
            } else {
                ccxt.AddElementToObject(request, "to", this.Seconds())
                ccxt.AddElementToObject(request, "from", ccxt.Subtract(ccxt.GetValue(request, "to"), (ccxt.Multiply(limit, this.ParseTimeframe(timeframe)))))
            }
        
            response:= (<-this.V4PublicNetGetCandles(this.Extend(request, params)))
            ccxt.PanicOnError(response)
            var candles interface{} = this.ConvertTradingViewToOHLCV(response, "t", "o", "h", "l", "c", "v")
        
            ch <- this.ParseOHLCVs(candles, market, timeframe, since, limit)
            return nil
        
            }()
            return ch
        }
