func  (this *mercado) OrdersToTrades(orders interface{}) interface{}  {
    var result interface{} = []interface{}{}
    for i := 0; ccxt.IsLessThan(i, ccxt.GetArrayLength(orders)); i++ {
        var trades interface{} = this.SafeValue(ccxt.GetValue(orders, i), "trades", []interface{}{})
        for y := 0; ccxt.IsLessThan(y, ccxt.GetArrayLength(trades)); y++ {
            ccxt.AppendToArray(&result, ccxt.GetValue(trades, y))
        }
    }
    return result
}
func  (this *mercado) Sign(path interface{}, optionalArgs ...interface{}) interface{}  {
    api := ccxt.GetArg(optionalArgs, 0, "public")
    _ = api
    method := ccxt.GetArg(optionalArgs, 1, "GET")
    _ = method
    params := ccxt.GetArg(optionalArgs, 2, map[string]interface{} {})
    _ = params
    headers := ccxt.GetArg(optionalArgs, 3, nil)
    _ = headers
    body := ccxt.GetArg(optionalArgs, 4, nil)
    _ = body
    var url interface{} = ccxt.Add(ccxt.GetValue(ccxt.GetValue(this.Urls, "api"), api), "/")
    var query interface{} = this.Omit(params, this.ExtractParams(path))
    if ccxt.IsTrue(ccxt.IsTrue(ccxt.IsTrue((ccxt.IsEqual(api, "public"))) || ccxt.IsTrue((ccxt.IsEqual(api, "v4Public")))) || ccxt.IsTrue((ccxt.IsEqual(api, "v4PublicNet")))) {
        url = ccxt.Add(url, this.ImplodeParams(path, params))
        if ccxt.IsTrue(ccxt.GetArrayLength(ccxt.ObjectKeys(query))) {
            url = ccxt.Add(url, ccxt.Add("?", this.Urlencode(query)))
        }
    } else {
        this.CheckRequiredCredentials()
        url = ccxt.Add(url, ccxt.Add(this.Version, "/"))
        var nonce interface{} = this.Nonce()
        body = this.Urlencode(this.Extend(map[string]interface{} {
            "tapi_method": path,
            "tapi_nonce": nonce,
        }, params))
        var auth interface{} = ccxt.Add(ccxt.Add(ccxt.Add(ccxt.Add("/tapi/", this.Version), "/"), "?"), body)
        headers = map[string]interface{} {
            "Content-Type": "application/x-www-form-urlencoded",
            "TAPI-ID": this.ApiKey,
            "TAPI-MAC": this.Hmac(this.Encode(auth), this.Encode(this.Secret), ccxt.Sha512),
        }
    }
    return map[string]interface{} {
        "url": url,
        "method": method,
        "body": body,
        "headers": headers,
    }
}
func  (this *mercado) HandleErrors(httpCode interface{}, reason interface{}, url interface{}, method interface{}, headers interface{}, body interface{}, response interface{}, requestHeaders interface{}, requestBody interface{}) interface{}  {
    if ccxt.IsTrue(ccxt.IsEqual(response, nil)) {
        return nil
    }
    //
    // todo add a unified standard handleErrors with this.exceptions in describe()
    //
    //     {"status":503,"message":"Maintenancing, try again later","result":null}
    //
    var errorMessage interface{} = this.SafeValue(response, "error_message")
    if ccxt.IsTrue(!ccxt.IsEqual(errorMessage, nil)) {
        panic(ccxt.ExchangeError(ccxt.Add(ccxt.Add(this.Id, " "), this.Json(response))))
    }
    return nil
}


